import base64
import os

icons = {
    "hoc_on.png": "",
    "luyen_de.png": "",
    "luyen_phan.png": "",
    "luyen_chudiem.png": ""
}

out_dir = "/Users/anh/Documents/Tiếng anh thi vào 10/public/images"
os.makedirs(out_dir, exist_ok=True)

for name, b64 in icons.items():
    p = os.path.join(out_dir, name)
    with open(p, "wb") as f:
        f.write(base64.b64decode(b64))
    print(f"Saved {p}")
